import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"构建与打包","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/build.md","filePath":"zh/dev/build.md"}'),l={name:"zh/dev/build.md"};function i(c,e,t,d,p,r){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="构建与打包" tabindex="-1">构建与打包 <a class="header-anchor" href="#构建与打包" aria-label="Permalink to &quot;构建与打包&quot;">​</a></h1><p>构建系统的开发者视图。用户级指南见仓库根部的 <a href="./../root/BUILDING.html">BUILDING.md</a> - 本页补充开发者工作流的 细节。</p><h2 id="你真正会用到的目标" tabindex="-1">你真正会用到的目标 <a class="header-anchor" href="#你真正会用到的目标" aria-label="Permalink to &quot;你真正会用到的目标&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -j$(nproc) kernel     # fast inner loop: ELF only</span></span>
<span class="line"><span>make iso                   # + bootable ISO</span></span>
<span class="line"><span>make userprogs             # regenerate the embedded program registry</span></span>
<span class="line"><span>make test                  # host unit tests (no QEMU needed)</span></span>
<span class="line"><span>make run-bios              # boot the ISO</span></span>
<span class="line"><span>make all                   # userprogs + kernel + ISO + src zip + OTA</span></span>
<span class="line"><span>make clean                 # start fresh</span></span>
<span class="line"><span>make reproducible-check    # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><h2 id="应用内嵌链" tabindex="-1">应用内嵌链 <a class="header-anchor" href="#应用内嵌链" aria-label="Permalink to &quot;应用内嵌链&quot;">​</a></h2><p><code>make userprogs</code>（属于 <code>make all</code>，也属于过期门禁）运行 <code>tools/gen_userprogs.py</code>：它发现每个 <code>ocos/l1apps/&lt;name&gt;/</code> 文件夹</p><ul><li>每个平铺的旧式程序，逐个独立环境编译（<code>-I ocos/interface</code>）， 按镜像模式链接，生成每个应用的 i18n 表，并写出 <code>ocos/kernel/userprogs_data.h</code>（blob + <code>OC_USERPROGS[]</code> 注册表）。 没有任何手工注册；一个新文件夹就是一条新命令。</li></ul><p>过期门禁：任何比生成头更新的源文件、接口头或 i18n json 都会强制 重新生成 - <code>make dist</code> 在内嵌内容过期时失败。</p><h2 id="编译缓存让内层循环变快" tabindex="-1">编译缓存让内层循环变快 <a class="header-anchor" href="#编译缓存让内层循环变快" aria-label="Permalink to &quot;编译缓存让内层循环变快&quot;">​</a></h2><p><code>tools/oc_cc.sh</code> 用一个内容寻址缓存包装每条编译规则： 键 = 编译器标识 + 完整标志集 + 源内容哈希 + 每个头文件依赖的 内容哈希。</p><ul><li>热对象与冷对象逐字节一致。</li><li><code>make cache-stats</code> / <code>make cache-clear</code> 管理它。</li><li>过期的缓存条目不可能存在：任何头文件编辑都会改变键。</li></ul><h2 id="版本号与构建号" tabindex="-1">版本号与构建号 <a class="header-anchor" href="#版本号与构建号" aria-label="Permalink to &quot;版本号与构建号&quot;">​</a></h2><ul><li><code>OC_RELEASE_VERSION</code> 默认取 Makefile 中的版本字面量；可在 命令行覆盖（<code>make OC_RELEASE_VERSION=3.0.0-test1 iso</code>），它 会进入横幅、<code>uname -a</code>、OTA 清单和 ISO 卷 ID。</li><li><code>OC_KERNEL_BUILD</code> = <code>git rev-list --count HEAD</code> + 永久的 +21 对齐偏移（<code>OC_KERNEL_BUILD_OFFSET := 21</code>）- 它在发布时 供给 <code>uname</code> 和 update.json 的 &quot;build&quot; 字段。数值比较 （BUG-0347）使 OTA 检查感知构建号。</li><li>版本重编译触发器（<code>kernel/generated/version_gen.h</code>， cmp 守卫）让 -D 标志的变化对依赖图可见 - 新代码上挂着旧横幅 的情况不会再发生。</li></ul><h2 id="打包确定性" tabindex="-1">打包确定性 <a class="header-anchor" href="#打包确定性" aria-label="Permalink to &quot;打包确定性&quot;">​</a></h2><ul><li><strong>SRC zip</strong>（<code>make src-zip</code>）：一次 <code>git archive</code> - 树序、 提交 mtime、索引权限；同一提交逐字节一致。</li><li><strong>OTA</strong>（<code>make ota</code>）：内核 ELF + 清单；清单携带构建日 （UTC），因此包在同一天内逐字节可复现。</li><li><strong>ELF</strong>：树中任何地方都没有 <code>__DATE__</code>/<code>__TIME__</code>/ <code>__TIMESTAMP__</code>（一个 make 门禁会 grep 它们），固定链接顺序， <code>strip --strip-debug</code> 移除携带路径的节。</li></ul><h2 id="多配置与交叉构建-开发者注记" tabindex="-1">多配置与交叉构建（开发者注记） <a class="header-anchor" href="#多配置与交叉构建-开发者注记" aria-label="Permalink to &quot;多配置与交叉构建（开发者注记）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # .config with everything on</span></span>
<span class="line"><span>make menuconfig         # interactive (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_NVME=n iso  # hardware profile: NVME off</span></span>
<span class="line"><span>make CONFIG_AHCI=n CONFIG_VIRTIO_BLK=n iso</span></span>
<span class="line"><span>make ARCH=arm64         # PL011 bring-up shell ELF</span></span>
<span class="line"><span>make ARCH=riscv         # NS16550A bring-up shell ELF</span></span></code></pre></div><p>配置器生成 <code>kernel/generated/config_gen.h</code>，其中是带比较守卫的 宏（3.0.0 的旋钮是硬件配置选项 NVME / AHCI / VIRTIO_BLK；TUI 与 CJK 管线始终编译在内）。被禁用的驱动改接到桩，绝不删除 代码。</p><h2 id="可脚本化的-api" tabindex="-1">可脚本化的 API <a class="header-anchor" href="#可脚本化的-api" aria-label="Permalink to &quot;可脚本化的 API&quot;">​</a></h2><p><code>tools/build.sh</code> 还兼作函数库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/build.sh</span></span>
<span class="line"><span>build_all; build_iso; config_load; cache_lookup; cross_compile ...</span></span>
<span class="line"><span>tools/build.sh api-selftest     # verifies the spec&#39;d interfaces</span></span></code></pre></div><p>发布自动化（见 <a href="./../release/process.html">../release/process.md</a>） 组合调用这些函数，而不是解析 make 输出。</p>`,22)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
